mapper.select:
SELECT id, purpose, phone_fingerprint, browser_fingerprint, actor_user_id, scheme_name, state,
       attempts, verification_token, expires_at, result_user_id, result_code, created_at
  FROM sms_verification_challenge WHERE id = #{id}

mapper.update:
UPDATE sms_verification_challenge SET state = 'SUPERSEDED', verification_token = NULL
 WHERE phone_fingerprint = #{phone} AND purpose = #{purpose}
   AND state IN ('SENDING', 'SENT', 'VERIFYING', 'VERIFIED')
